typedef float rational_t;

class widget
{
public:
  virtual ~widget();
  void scale_to(rational_t hs, rational_t vs);
  virtual void set_subrect(int x0, int y0, int x1, int y1);
  virtual void set_origin(short x, short y);
protected:
  char padding0[0x34];
  short orig_x;
  short orig_y;
  char padding1[0xE4];
  rational_t abs_S[2];
  char padding2[0x18];
};

class bitmap_widget: public widget
{
public:
  virtual ~bitmap_widget();
  virtual void scale_to(rational_t hs, rational_t vs);
  void set_tc();
  bool is_open() { return (flags & 0x00000002); }
protected:
  unsigned int flags;
  rational_t w;
  rational_t h;
};

void bitmap_widget::scale_to( rational_t hs, rational_t vs )
{
  if ( !is_open() ) return;
  widget::scale_to( hs, vs );
  set_tc();
  set_subrect( 0.0f, 0.0f, w * abs_S[0], h * abs_S[1] );
  if ( orig_x != 0.0f || orig_y != 0.0f )
  {
    set_origin( short( w * abs_S[0] / 2.0f + 0.5f ), short( h * abs_S[1] / 2.0f + 0.5f ) );
  }
}
